package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.jxpath.Expression;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CoreOperationCompare_findMatch_TriageGen1Test {

    private CoreOperationCompare sut;
    private Expression mockExpr1;
    private Expression mockExpr2;

    @Before
    public void setUp() {
        mockExpr1 = mock(Expression.class);
        mockExpr2 = mock(Expression.class);
        // Since the constructor is public and requires two Expressions
        sut = new CoreOperationCompare(mockExpr1, mockExpr2) {
            // We must override contains because findMatch calls it. 
            // In the real class, contains is a protected method of the same class.
            @Override
            protected boolean contains(Iterator it, Object value) {
                // Simple implementation to mimic the logic expected by findMatch
                // Note: The real implementation likely iterates through the iterator
                while (it.hasNext()) {
                    if (equals(it.next(), value)) {
                        return true;
                    }
                }
                return false;
            }

            @Override
            protected boolean equals(Object l, Object r) {
                return l != null && l.equals(r);
            }
        };
    }

    @Test
    public void testFindMatch_BothIteratorsEmpty_ReturnsFalse() {
        Iterator<String> lit = Collections.emptyIterator();
        Iterator<String> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse("Should return false when both iterators are empty", result);
    }

    @Test
    public void testFindMatch_LitEmptyRitNotEmpty_ReturnsFalse() {
        Iterator<String> lit = Collections.emptyIterator();
        Iterator<String> rit = Arrays.asList("A", "B").iterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse("Should return false when left iterator is empty", result);
    }

    @Test
    public void testFindMatch_LitNotEmptyRitEmpty_ReturnsFalse() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Collections.emptyIterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse("Should return false when right iterator is empty", result);
    }

    @Test
    public void testFindMatch_MatchFound_ReturnsTrue() {
        Iterator<String> lit = Arrays.asList("A", "B", "C").iterator();
        Iterator<String> rit = Arrays.asList("X", "B", "Y").iterator();

        boolean result = sut.findMatch(lit, rit);

        assertTrue("Should return true when a match is found", result);
    }

    @Test
    public void testFindMatch_NoMatchFound_ReturnsFalse() {
        Iterator<String> lit = Arrays.asList("A", "B", "C").iterator();
        Iterator<String> rit = Arrays.asList("X", "Y", "Z").iterator();

        boolean result = sut.findMatch(lit, rit);

        assertFalse("Should return false when no elements match", result);
    }

    @Test
    public void testFindMatch_MatchAtFirstElementOfRit_ReturnsTrue() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Arrays.asList("A", "Z").iterator();

        boolean result = sut.findMatch(lit, rit);

        assertTrue("Should return true when first element of rit matches", result);
    }

    @Test
    public void testFindMatch_MatchAtLastElementOfRit_ReturnsTrue() {
        Iterator<String> lit = Arrays.asList("A", "B").iterator();
        Iterator<String> rit = Arrays.asList("Z", "B").iterator();

        boolean result = sut.findMatch(lit, rit);

        assertTrue("Should return true when last element of rit matches", result);
    }
}
